function FaintDoodle({ variant }) {
  if (variant === 'github') {
    return <GithubDoodle />
  }
  if (variant === 'gitlab') {
    return <GitlabDoodle />
  }
  return null
}

export default function App() {
  const [theme, setTheme] = useState(getInitialTheme)

  useEffect(() => {
    document.documentElement.dataset.theme = theme
    window.localStorage.setItem('adroit-theme', theme)
  }, [theme])

  return (
    <div className="app">
      {/* ---------- Sidebar ---------- */}
      <aside className="sidebar">
        <div className="side-top">
          <div className="brand">
            <AdroitMark />
            <span className="brand-name">Adroit</span>
          </div>
          <button className="icon-btn" aria-label="Collapse sidebar">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6"><rect x="3" y="4" width="18" height="16" rx="4" /><path d="M10 9.5v5" strokeLinecap="round" /></svg>
          </button>
        </div>

        <button className="new-btn">New project</button>

        <div className="side-section">
          <p className="side-label">WORKSPACE</p>
          <nav className="side-nav">
            <a className="side-link" href="#"><Icon d={icons.overview} /> Overview</a>
            <a className="side-link active" href="#"><Icon d={icons.projects} /> Projects <span className="count">6</span></a>
            <a className="side-link" href="#"><Icon d={icons.activity} /> Activity</a>
          </nav>
        </div>

        <div className="side-section">
          <p className="side-label">RECENT PROJECTS</p>
          <nav className="side-nav recent">
            <a href="#"><span className="mini-icon ring">N</span> Orbit Web</a>
            <a href="#"><span className="mini-icon ring">N</span> Consul Client</a>
            <a href="#"><span className="mini-icon py">🐍</span> Adroit-mcp</a>
            <a href="#"><span className="mini-icon infinity">∞</span> Atlas API</a>
            <a href="#"><span className="mini-icon globe">🌐</span> Bayo's folio</a>
          </nav>
        </div>

        <div className="side-bottom">
          <button className="doc-btn">Documentation <Icon d={icons.help} size={15} /></button>
          <nav className="side-nav">
            <a className="side-link" href="#"><Icon d={icons.changelog} size={17} /> Changelog</a>
            <a className="side-link" href="#"><Icon d={icons.settings} size={17} /> Settings</a>
            <a className="side-link" href="#"><Icon d={icons.billing} size={17} /> Billing</a>
          </nav>
          <div className="side-user">
            <img src="https://i.pravatar.cc/64?img=12" alt="Adebayo" />
            <span>Adebayo Olowofoye…</span>
          </div>
        </div>
      </aside>

      {/* ---------- Main ---------- */}
      <div className="main">
        <header className="topbar">
          <h1>Bayo Workspace</h1>
          <div className="top-actions">
            <button className="search">
              <span>Search or jump to…</span>
              <kbd>⌘ K</kbd>
            </button>
            <button className="icon-btn theme-toggle" aria-label={theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'} onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}>
              {theme === 'dark' ? (
                <svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                  <circle cx="12" cy="12" r="4" />
                  <path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4" />
                </svg>
              ) : (
                <svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                  <path d="M20 13.2A8 8 0 1 1 10.8 4a6.5 6.5 0 0 0 9.2 9.2Z" />
                </svg>
              )}
            </button>
            <button className="icon-btn bell" aria-label="Notifications"><Icon d={icons.bell} size={19} /></button>
            <img className="avatar" src="https://i.pravatar.cc/64?img=12" alt="profile" />
          </div>
        </header>

        <main className="content">
          <section className="card">
            <div className="card-head">
              <div>
                <h2>New project</h2>
                <p>Choose how you want to start your project</p>
              </div>
              <div className="banner-art" aria-hidden="true" />
            </div>

            <div className="card-body">
              <div className="import-col">
                <button className="import-cell">
                  <FaintDoodle variant="github" />
                  <span className="import-icon"><GithubIcon /></span>
                  <span className="import-title">Import from GitHub</span>
                  <span className="import-sub">Connect a repository from your GitHub account</span>
                </button>
                <button className="import-cell">
                  <FaintDoodle variant="gitlab" />
                  <span className="import-icon"><GitlabIcon /></span>
                  <span className="import-title">Import from GitLab</span>
                  <span className="import-sub">Connect a repository from your GitLab account</span>
                </button>
              </div>

              <div className="upload-cell">
                <ZipIllustration />
                <h3>Upload a ZIP file</h3>
                <p>Upload your .zip project and configure<br />it for deployment.</p>
                <label className="zip-btn">
                  Choose ZIP file
                  <input type="file" accept=".zip" hidden onChange={(e) => { if (e.target.files?.[0]) alert(`Selected: ${e.target.files[0].name}`) }} />
                </label>
              </div>
            </div>
          </section>
        </main>

        <footer className="statusbar">
          <span className="bars" aria-hidden="true"><i /><i /><i /><i /></span>
          All systems operational
        </footer>
      </div>
    </div>
  )
}
